const parcels = {
  "P-101": { address: "12 River Lane", area: "680 m²" },
  "P-102": { address: "4 Oak Street", area: "420 m²" },
};

function showParcel(id) {
  const parcel = parcels[id];
  if (!parcel) return;
  const details = document.querySelector("#details");
  details.textContent = `${id} — ${parcel.address} — ${parcel.area}`;
  details.hidden = false;
}

document.querySelector("#map").addEventListener("click", (event) => {
  const parcelButton = event.target.closest(".parcel");
  if (!parcelButton) return;
  showParcel(parcelButton.dataset.parcelId);
});

// Keep the fixture route available for deterministic previews and checks.
const fixture = new URLSearchParams(location.search).get("fixture");
if (fixture) showParcel(fixture);
